package pe.edu.lab16.asistentes;import org.springframework.stereotype.Service;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.util.List;
@Service public class AsistenteService{private final AsistenteRepository repo;public AsistenteService(AsistenteRepository r){repo=r;}public List<Asistente> listar(){return repo.findAll();}public Asistente obtener(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Asistente no encontrado"));}public Asistente crear(AsistenteRequest r){Asistente a=new Asistente();aplicar(a,r);return repo.save(a);}public Asistente actualizar(Long id,AsistenteRequest r){Asistente a=obtener(id);aplicar(a,r);return repo.save(a);}public void eliminar(Long id){repo.delete(obtener(id));}private void aplicar(Asistente a,AsistenteRequest r){a.setNombres(r.nombres());a.setCorreo(r.correo());a.setTelefono(r.telefono());}}
